"use strict";
var axios = require('axios');
var year = 2016;
function getSido() {
    return axios
        .post('https://sgis.kostat.go.kr/ServiceAPI/map/sidoAddressList.json', 
    // { base_year: 2016 }
    "base_year=" + year)
        .then(function (res) { return res.data.result.sidoList; })
        .then(function (sidoList) {
        return Promise.all(sidoList.map(function (sido) {
            return getSigungu(sido.sido_cd).then(function (sggList) {
                sido.sggList = sggList;
                return sido;
            });
        }));
    });
}
function getSigungu(sidoCode) {
    return axios
        .post('https://sgis.kostat.go.kr/ServiceAPI/map/sggAddressList.json', 
    // { base_year: 2016 }
    "sido_cd=" + sidoCode + "&base_year=" + year)
        .then(function (res) { return res.data.result.sggList; })
        .then(function (sggList) {
        return Promise.all(sggList.map(function (sgg) {
            return getAdm(sidoCode, sgg.sgg_cd).then(function (admList) {
                sgg.admList = admList;
                return sgg;
            });
        }));
    });
}
// 읍동면?
function getAdm(sidoCode, sggCode) {
    return axios
        .post('https://sgis.kostat.go.kr/ServiceAPI/map/admAddressList.json', 
    // { base_year: 2016 }
    "sido_cd=" + sidoCode + "&sgg_cd=" + sggCode + "&base_year=" + year)
        .then(function (res) { return res.data.result.admList; })
        .catch(function (e) {
        console.log('e', e);
        return [];
    });
}
